import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        new PalindromeSolver();
    }
}

class PalindromeSolver {
    PalindromeSolver() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int length = Integer.parseInt(reader.readLine());
        String line = reader.readLine();
        char[] word = line.toCharArray();
        int[] values = new int[length];
        String[] valsStr = reader.readLine().split(" ");
        for (int i = 0; i < length; i++) {
            values[i] = Integer.parseInt(valsStr[i]);
        }
        int[] badLettersCount = new int[26];
        int totalPairs = 0;
        for (int i = 0; i < length / 2; i++) {
            if (word[i] == word[length - i - 1]) {
                badLettersCount[word[i] - 'a']++;
                totalPairs++;
            }
        }
        int maxBadCount = 0;
        boolean badFlag = false;
        int badIndex = -1;
        for (int i = 0; i < 26; i++) {
            if (badLettersCount[i] * 2 > totalPairs) {
                badFlag = true;
                badIndex = i;
            }
        }
        if (!badFlag) {
            long sumCost = 0;
            for (int i = 0; i < length / 2; i++) {
                if (word[i] != word[length - i - 1]) {
                    sumCost += values[i] + values[length - i - 1];
                } else {
                    sumCost += Math.max(values[i], values[length - i - 1]);
                }
            }
            out.println(sumCost);
        } else {
            int excess = badLettersCount[badIndex] - (totalPairs - badLettersCount[badIndex]);
            ArrayList<Integer> minCosts = new ArrayList<>();
            for (int i = 0; i < length / 2; i++) {
                if (word[i] != word[length - i - 1] && word[i] != ('a' + badIndex) && word[length - i - 1] != ('a' + badIndex)) {
                    minCosts.add(Math.min(values[i], values[length - i - 1]));
                }
            }
            Collections.sort(minCosts);
            long totalCost = 0;
            for (int i = 0; i < length / 2; i++) {
                if (word[i] == word[length - i - 1]) {
                    totalCost += Math.max(values[i], values[length - i - 1]);
                } else {
                    totalCost += values[i] + values[length - i - 1];
                }
            }
            for (int i = 0; i < excess && i < minCosts.size(); i++) {
                totalCost -= minCosts.get(i);
            }
            out.println(totalCost);
        }
        out.close();
    }
}
